static bool gd32h77x_fd_valid(int fd, const TUYA_FD_SET_T *fds)
{
    return fds != NULL && fd >= 0 && (unsigned)fd < (unsigned)TUYA_FD_MAX_COUNT;
}

static bool gd32h77x_ipv4_parse(const char *text, uint32_t *address)
{
    uint32_t result = 0;

    if (text == NULL || address == NULL) {
        return false;
    }
    for (unsigned octet_index = 0; octet_index < 4; ++octet_index) {
        unsigned octet = 0;
        unsigned digits = 0;
        const char *octet_start = text;
        if (*text < '0' || *text > '9') {
            return false;
        }
        do {
            unsigned digit = (unsigned)(*text++ - '0');
            if (octet > 25U || (octet == 25U && digit > 5U)) {
                return false;
            }
            octet = octet * 10U + digit;
            ++digits;
        } while (*text >= '0' && *text <= '9');
        if (digits > 1U && *octet_start == '0') {
            return false;
        }
        result = (result << 8) | octet;
        if (octet_index < 3U) {
            if (*text++ != '.') {
                return false;
            }
        } else if (*text != '\0') {
            return false;
        }
    }
    *address = result;
    return true;
}
