/**
 * @brief Change ip string to address
 *
 * @param[in] ip_str: ip string
 *
 * @note This API is used to change ip string to address.
 *
 * @return ip address
 */
TUYA_IP_ADDR_T tkl_net_str2addr(const char *ip_str)
{
    // --- BEGIN: user implements ---
    uint32_t address;
    if (!gd32h77x_ipv4_parse(ip_str, &address)) {
        /* Matches the standard T5AI API's invalid-address sentinel. */
        return UINT32_MAX;
    }
    return (TUYA_IP_ADDR_T)address;
    // --- END: user implements ---
}

/**
 * @brief Change ip address to string
 *
 * @param[in] ipaddr: ip address
 *
 * @note This API is used to change ip address(in host byte order) to string(in IPv4 numbers-and-dots(xx.xx.xx.xx)
 * notion).
 *
 * @return ip string
 */
char *tkl_net_addr2str(const TUYA_IP_ADDR_T ipaddr)
{
    // --- BEGIN: user implements ---
    static char address[16];
    (void)snprintf(address, sizeof(address), "%u.%u.%u.%u", (unsigned)((ipaddr >> 24) & 255U),
                   (unsigned)((ipaddr >> 16) & 255U), (unsigned)((ipaddr >> 8) & 255U), (unsigned)(ipaddr & 255U));
    return address;
    // --- END: user implements ---
}

